using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// Build the chat client through the MEAI abstraction.
IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// Instantiate the tools the agent can use.
var researchTools = new ResearchTools();
AITool[] tools =
[
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(researchTools.SaveNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
];

const string instructions = """
    You are a research assistant. When given a topic you:
    1. Search the web for relevant information using the SearchWeb tool.
    2. Save important findings as notes using the SaveNote tool.
    3. Perform additional searches to fill knowledge gaps.
    4. Once you have gathered enough information, retrieve all notes with GetNotes
       and produce a well-structured summary with key findings and sources.
    When you are done, end your final message with [RESEARCH_COMPLETE].
    """;

var innerAgent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: tools);

// Wrap in a loop that re-invokes until the agent emits the completion marker.
var agent = new LoopAgent(
    innerAgent,
    evaluator: new CompletionMarkerLoopEvaluator("[RESEARCH_COMPLETE]"),
    options: new LoopAgentOptions { MaxIterations = 10 });

// Prompt the user for a topic (or accept one from the command line).
string topic;
if (args.Length > 0)
{
    topic = string.Join(' ', args);
}
else
{
    Console.Write("Enter a research topic: ");
    topic = Console.ReadLine()?.Trim() ?? "artificial intelligence";
}

Console.WriteLine($"\nResearching: {topic}\n");

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

var response = await agent.RunAsync($"Research the following topic: {topic}", options: runOptions);

// Print the final response.
foreach (var message in response.Messages)
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.WriteLine(message.Text);
    }
}

// -------------------------------------------------------------------
// Tool implementations
// -------------------------------------------------------------------

/// <summary>Provides web search and note-taking tools for the research agent.</summary>
sealed class ResearchTools
{
    private static readonly HttpClient s_httpClient = new();
    private readonly List<string> _notes = [];

    [Description("Searches the web for information on a query and returns a list of result snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        // Uses the DuckDuckGo Instant Answer API as a free, key-less search source.
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

        try
        {
            using var response = await s_httpClient.GetAsync(url);
            response.EnsureSuccessStatusCode();

            using var doc = await JsonDocument.ParseAsync(await response.Content.ReadAsStreamAsync());
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract (main summary)
            var abs = root.GetProperty("Abstract").GetString();
            if (!string.IsNullOrWhiteSpace(abs))
            {
                var src = root.GetProperty("AbstractSource").GetString();
                results.Add($"[{src}] {abs}");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var related))
            {
                foreach (var item in related.EnumerateArray().Take(5))
                {
                    var text = item.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                        results.Add(text);
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No results found for '{query}'. Try a different search term.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Saves a research note. Use this to record important findings.")]
    public string SaveNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Retrieves all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n", _notes.Select((n, i) => $"Note #{i + 1}: {n}"));
    }
}

